#include "nsb_client.h" #include <iostream> int main() { // Initialize std::string server = "127.0.0.1"; int port = 65432; nsb::NSBAppClient app("node0", server, port); // Send std::string outgoing = "Hello, World!"; app.send("node1", outgoing); // Receive nsb::MessageEntry entry = app.receive(); if (entry.exists()) { std::cout << "Source: " << entry.source << "
" << "Dest: " << entry.destination << "
" << "Payload: " << entry.payload_obj << "
"; } return 0; }
